 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Horizontal bands have a single-cell zero hole between same-color runs.
    # Each hole marks a vertical channel; successive bands color the intervals
    # in that channel, and the bottom vertical marker colors the final interval.
    events = {}
    horizontal_rows = []
    for r, row in enumerate(grid):
        holes = []
        for c in range(1, w - 1):
            if row[c] == 0 and row[c-1] != 0 and row[c+1] != 0 and row[c-1] == row[c+1]:
                holes.append((c, row[c-1]))
        if holes:
            horizontal_rows.append(r)
            for c, color in holes:
                events.setdefault(c, []).append((r, color))
    for c, evs in events.items():
        # Draw each horizontal band color from the preceding boundary through
        # its own row; the hole cell is bridged as part of the band.
        start = 0
        for r, color in evs:
            for rr in range(start, r + 1):
                out[rr][c] = color
            start = r + 1
        # A vertical marker below the bands supplies the color of the bottom
        # segment, extending upward to the last horizontal band.
        markers = [(r, grid[r][c]) for r in range(h) if r > evs[-1][0] and grid[r][c] != 0]
        if markers:
            color = markers[0][1]
            for rr in range(start, h):
                out[rr][c] = color
    return out
