def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    events = {}
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            if row[c] == 0 and row[c-1] != 0 and row[c+1] != 0 and row[c-1] == row[c+1]:
                events.setdefault(c, []).append((r, row[c-1]))
    for c, evs in events.items():
        start = 0
        for r, color in evs:
            for rr in range(start, r + 1):
                out[rr][c] = color
            start = r + 1
        markers = [grid[rr][c] for rr in range(start, h) if grid[rr][c] != 0]
        if markers:
            for rr in range(start, h):
                out[rr][c] = markers[0]
    return out
